INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'W', 1, 'welcome', 'flow', NULL, NULL, 'Welcome', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '0.1', 2, 'statement', 'flow', NULL, NULL, 'Opening statement', NULL, 'This survey is about the opportunity to cover HNW clients, who have $5-20mm of liquid net worth.', 'Answer every question with these clients in mind.', 'Liquid net worth is cash and investments they could move, not home or business.', NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'break-I', 3, 'break', 'break', 'I', NULL, 'Chapter break', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '1.1', 4, 'question', 'checklist', 'I', NULL, 'The core: plan or advice', NULL, 'The core of a $5-20mm relationship is ________.', 'Both matter. Tap the one that''s closer to your view.', NULL, NULL, 'tradeCore', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '1.2', 5, 'question', 'checklist', 'I', NULL, 'HNW clients most value ___: attention or speed', NULL, 'HNW clients most value ________ in their banking providers.', 'Both matter. Tap the one that''s closer to your view.', NULL, NULL, 'tradeValue', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '1.3', 6, 'question', 'checklist', 'I', NULL, 'Why they choose us: name or banker', NULL, 'When a $5-20mm client chooses us, it''s mostly for ________.', 'Both matter. Tap the one that''s closer to your view.', NULL, NULL, 'tradeWin', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '1.4', 7, 'question', 'checklist', 'I', NULL, 'Investment advice: banker or central team', NULL, 'For a $5-20mm client, investment advice works better from ________.', 'Both can work. Tap the one that''s closer to your view.', NULL, NULL, 'tradeAdvice', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'break-II', 8, 'break', 'break', 'II', NULL, 'Chapter break', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.1', 9, 'question', 'text', 'II', NULL, 'What drew clients to J.P. Morgan: three reasons', 'Picture it five years after launch. J.P. Morgan has an industry-leading platform to cover HNW clients.', 'When those clients are asked what drew them to J.P. Morgan, they consistently say:', 'Write a few short sentences for each, up to the length of a tweet.', NULL, NULL, 'drewThem', 'Write all three, 3 characters or more each', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.2', 10, 'question', 'piles', 'II', NULL, 'Product sorter, 15 cards', NULL, 'Where does each product belong in our offer for $5-20mm clients?', 'Tap a pile for each card. 15 cards.', 'Assume we''re allowed to offer each one in your market.
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.2a', 11, 'followup', 'podium', 'II', '2.2', 'Top 3 products', 'These are the products in your Critical pile.', 'Which three products matter most to winning?', 'Pick your top 3, most important first.', NULL, 'Shows only if Critical holds more than 3 cards.', 'productsTop3', 'Pick 3', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.3', 12, 'question', 'configure', 'II', NULL, 'Ways of investing: where each belongs, what it covers, who helps', NULL, 'How would each way of investing work for a $5-20mm client?', 'Answer the three parts for each one.', 'Our core offerings are Core & Multi Asset, Manager Solutions, Focus Five, Vintage and the rest of our default range.', NULL, 'investWays', 'Answer all three parts for each (Not for HNW skips the other two; at least one product)', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.4', 13, 'question', 'track', 'II', NULL, 'How much customisation: standard to bespoke', NULL, 'For advisory and discretionary portfolios, how much customisation would you offer a $5-20mm client?', 'Tap one.', 'Think about what we could deliver well as client numbers grow.', 'Shows only if Engage or Entrust is not put in Not for HNW on 2.3.', 'choice', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.4a', 14, 'followup', 'checklist', 'II', '2.4', 'How many risk profiles', 'On risk profiles.', 'How many standard risk profiles would you offer these clients?', 'Tap one.', NULL, 'Shows only if 2.4 is shown.', 'riskProfiles', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.5', 15, 'question', 'piles', 'II', NULL, 'Service sorter, 12 cards in four groups', NULL, 'Where does each service belong in our offer for $5-20mm clients?', 'Tap a pile for each card. 12 cards.', 'Services are what we do for the client.', NULL, 'services', 'Sort all 12 cards', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.5a', 16, 'followup', 'podium', 'II', '2.5', 'Top 3 services', 'These are the services in your Critical pile.', 'Which three matter most to winning?', 'Pick your top 3, most important first.', NULL, 'Shows only if Critical holds more than 3 cards.', 'servicesTop3', 'Pick 3', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '2.6', 17, 'question', 'trays', 'II', NULL, 'Who is best placed to provide it', NULL, 'If clients want these, who is best placed to provide them?', 'Put each one in a tray. {n} items.', 'Another J.P. Morgan business means Chase where it operates, the CIB or Asset Management.', NULL, 'provide', 'Put every item in a tray', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'break-III', 18, 'break', 'break', 'III', NULL, 'Chapter break', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '3.1', 19, 'question', 'ladder', 'III', NULL, 'Share-of-wallet column', NULL, 'A typical $10mm client chooses us. With today''s offer, what share of their money would we hold?', 'Tap the column or type a percentage.', 'Count only their cash and investments.', NULL, 'wallet', 'Set today''s share, then each row, then all four together', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '3.2', 20, 'question', 'podium', 'III', NULL, 'Why move money to us: top 3 of 10', NULL, 'Why would a $5-20mm client move money to us rather than to their main bank?', 'Pick your top 3, most important first.', NULL, NULL, 'whyUs', 'Pick 3', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '3.3', 21, 'question', 'rank', 'III', NULL, 'What makes a client feel special', NULL, 'What makes a $5-20mm client feel most special with us?', 'Place all 10. Most important at 1.', NULL, NULL, 'special', 'Place all 10', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'break-IV', 22, 'break', 'break', 'IV', NULL, 'Chapter break', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '4.1', 23, 'question', 'sentence', 'IV', NULL, 'The HNW floor in my market', NULL, 'In my market, any client with more than $[    ]mm would demand services consistent with an HNW offering.', 'Type an amount in millions of US dollars.', 'Liquid net worth. It doesn''t have to match the $5-20mm range.', NULL, 'floor', 'Type an amount from $0.5mm to $50mm', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '4.1a', 24, 'followup', 'checklist', 'IV', '4.1', 'Where a client just below the floor goes', 'Then, clients just under that amount.', 'Where does a client just below $[X]mm go?', 'Tap one.', NULL, NULL, 'floorBelow', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '4.2', 25, 'question', 'sentence', 'IV', NULL, 'The move to UHNW coverage', NULL, 'At $[    ]mm in balances with us, I would [offer · suggest · require] a move to UHNW coverage.', 'Type an amount, then tap one word.', 'Deposits and investments with J.P. Morgan. Loans don''t count.', NULL, 'ceiling', 'A number and a word, or Never', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '4.3', 26, 'question', 'stamp', 'IV', NULL, 'Every client, above an amount, or none: 10 cards', NULL, 'Who gets each of these: every $5-20mm client, only those above an amount, or none?', 'Stamp each card. 10 cards.', 'Dedicated means they work with a fixed list of clients.', NULL, 'entitled', 'Stamp all 10 cards', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '4.3a', 27, 'followup', 'sentence', 'IV', '4.3', 'From what amount, for each role', 'Next, the amounts for those roles.', 'From what amount does a client get each one?', 'Type an amount for each role.', 'Liquid net worth, in millions of US dollars.', 'Shows only if a role (banker, investment specialist resource, WA, CA or CSS) is stamped Only above an amount. One row per such role.', 'entitledFrom', 'Type an amount for each row', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '4.4', 28, 'question', 'checklist', 'IV', NULL, 'Clients we already have', NULL, 'Some IPB clients today have $5-20mm. What happens to them at launch?', 'Tap one.', NULL, NULL, 'existing', 'Tap one', TRUE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'break-V', 29, 'break', 'break', 'V', NULL, 'Chapter break', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '5.1', 30, 'question', 'allocate-ledger', 'V', NULL, 'Ledger: the split, then banking and cash', NULL, 'A typical $10mm client chooses us. With today''s offer, how is their money split, and who holds it?', 'Type the split, then amounts in $mm.', 'Banking and cash means current accounts, deposits and money funds.', NULL, 'ledgerCash', 'Type the split, then make the Banking and cash column equal it', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '5.2', 31, 'question', 'allocate-ledger', 'V', NULL, 'Ledger: investments', NULL, 'The other $[X]mm is invested. Who holds it?', 'Type amounts in $mm. They must add up to $[X]mm.', 'If J.P. Morgan manages money inside a wrapper, count it as J.P. Morgan.', NULL, 'ledgerInvest', 'Make the Investments column add up to $[X]mm', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '5.2a', 32, 'followup', 'checklist', 'V', '5.2', 'Whose clients to try hardest to win', 'Who they bank with now.', 'Whose clients would you try hardest to win?', 'Tap one.', NULL, NULL, 'targetClient', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '5.3', 33, 'question', 'trays', 'V', NULL, 'Local bank or J.P. Morgan, 10 tiles', NULL, 'What will a $5-20mm client keep with their local bank, and what will they bring to us?', 'Put each one in a tray. 10 items.', NULL, NULL, 'locals', 'Put all 10 in a tray', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '5.3a', 34, 'followup', 'checklist', 'V', '5.3', 'Where the money is booked', 'This is only about the money that comes to us.', 'Where would you book that money?', 'Tap one.', NULL, NULL, 'booking', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '5.4', 35, 'question', 'sentence', 'V', NULL, 'Clients three years after launch', NULL, 'Three years after launch, I expect the IPB to have about [      ] clients with $5-20mm.', 'Type a number.', 'Relationships (families), not accounts.', NULL, 'expect3', 'Type a number from 0 to 200,000', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '5.4a', 36, 'followup', 'allocate-list', 'V', '5.4', 'Where those clients come from', 'Now, where they come from.', 'Where will those [N] clients come from?', 'Type a share for each. They must add up to 100%.', 'Count each family once. Families who bank with the IPB today count as clients we already have.', 'Shows only if the answer to 5.4 is more than 0.', 'sources', 'The shares must add up to exactly 100%', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'break-VI', 37, 'break', 'break', 'VI', NULL, 'Chapter break', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.1', 38, 'question', 'checklist', 'VI', NULL, 'In person, hybrid, virtual or digital', NULL, 'How would you cover a typical $5-20mm client?', 'Tap one.', NULL, NULL, 'coverage', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.1a', 39, 'followup', 'sentence', 'VI', '6.1', 'Clients per banker', 'Still on coverage.', 'About how many clients can one HNW banker cover effectively?', 'Type a number.', 'With today''s tools. Count relationships (families), not accounts.', NULL, 'bookToday', 'Type a number from 10 to 500', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.2', 40, 'question', 'sentence', 'VI', NULL, 'In-person meetings: the first year, then each year', NULL, 'The optimal number of in-person meetings with a client is [  ] in their first year and [  ] each year after that.', 'Type two numbers.', 'In person only. Calls and video don''t count.', NULL, 'meetings', 'Type two numbers from 0 to 24', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.2a', 41, 'followup', 'checklist', 'VI', '6.2', 'Where meetings take place', 'And the meetings themselves.', 'Where will most of those meetings take place?', 'Pick one or two.', NULL, 'Shows only if either number on 6.2 is 1 or more.', 'venues', 'Pick one or two', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.2b', 42, 'followup', 'track', 'VI', '6.2', 'How far away the banker can be', 'One more, about distance.', 'How far from the client can the banker be based and still serve them well?', 'Tap one.', NULL, NULL, 'distance', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.3', 43, 'question', 'piles', 'VI', NULL, 'The ideal banker, 12 cards', NULL, 'How much does each of these matter in the ideal HNW banker?', 'Tap a pile for each card. 12 cards.', NULL, NULL, 'banker', 'Sort all 12 cards', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.3a', 44, 'followup', 'podium', 'VI', '6.3', 'Top 3 qualities', 'Take the qualities in your Critical pile.', 'Which three matter most in an HNW banker?', 'Pick your top 3, most important first.', NULL, 'Shows only if Critical holds more than 3 cards.', 'bankerTop3', 'Pick 3', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.4', 45, 'question', 'bottle', 'VI', NULL, 'Seniority of a team of 10', NULL, 'Picture a team of 10 HNW bankers. How senior do they need to be?', 'Tap a jug to add 1 banker.', NULL, NULL, 'seniority', 'Place exactly 10 bankers', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '6.4a', 46, 'followup', 'sentence', 'VI', '6.4', 'Of 10 new bankers, how many from inside', 'Where those bankers come from.', 'Of every 10 HNW bankers we add, how many could realistically come from inside J.P. Morgan?', 'Type a number.', 'Inside means our Associates, Analyst-to-Advisor (A2A) graduates and people moving from other J.P. Morgan teams.', NULL, 'grownInside', 'Type a number from 0 to 10', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'break-VII', 47, 'break', 'break', 'VII', NULL, 'Chapter break', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '7.1', 48, 'question', 'track', 'VII', NULL, 'Requests handled without a banker', NULL, 'Three years after launch, what share of a client''s requests and transactions will be handled without a banker?', 'Tap the line to set your answer.', 'Count payments, trades, documents and questions, not log-ins. JPOI, the web and the service team count as without a banker.', NULL, 'digitalShare', 'Tap the line', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '7.2', 49, 'question', 'piles', 'VII', NULL, 'Digital features, 12 cards', NULL, 'Which digital features does a $5-20mm offer need?', 'Tap a pile for each card. 12 cards.', 'JPOI is the app these clients will use.', NULL, 'digitalFeatures', 'Sort all 12 cards', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '7.2a', 50, 'followup', 'podium', 'VII', '7.2', 'Top 3 digital features', 'The features you put in Critical to winning.', 'Which three matter most to winning?', 'Pick your top 3, most important first.', NULL, 'Shows only if Critical holds more than 3 cards.', 'digitalTop3', 'Pick 3', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '7.3', 51, 'question', 'track', 'VII', NULL, 'How much AI can do for a banker', NULL, 'How much can AI do for an HNW banker, three years after launch?', 'Tap one.', 'We mean AI tools that our own staff use.', NULL, 'aiLevel', 'Tap one', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '7.4', 52, 'question', 'stamp', 'VII', NULL, 'AI across the client life cycle, 8 cards', NULL, 'Three years after launch, how will people and AI split the work at each step with a client?', 'Stamp each card. 8 cards.', 'Think of the work involved, not how much the step matters.', NULL, 'aiStages', 'Stamp all 8 cards', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '7.4a', 53, 'followup', 'sentence', 'VII', '7.4', 'Clients per banker with AI', 'Now, what that means for a banker''s book.', 'With the AI you just described, how many clients can one HNW banker cover effectively?', 'Type a number.', 'Count relationships (families), not accounts.', NULL, 'bookWithAi', 'Type a number from 10 to 1,000', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', 'break-VIII', 54, 'break', 'break', 'VIII', NULL, 'Chapter break', NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '8.1', 55, 'question', 'stamp', 'VIII', NULL, 'Changes to price, 12 cards', NULL, 'Would you make each of these price changes for $5-20mm clients?', 'Stamp each card. {n} cards.', 'These changes would apply only to the HNW offer.', NULL, 'pricing', 'Stamp all 12 cards', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '8.1a', 56, 'followup', 'stamp', 'VIII', '8.1', 'Only one change', 'We can''t do everything at once.', 'If we could make only one of these changes, which one?', 'Tap one line.', NULL, 'Shows only if two or more cards are stamped Do it or Pilot it.', 'pricingOne', 'Tap one line', FALSE);
INSERT INTO step (version, step_id, seq, kind, template, chapter, parent_step_id, title, bridge, question, instruction, notes, show_condition, store, completion_rule, wave1_only) VALUES ('v3', '8.2', 57, 'question', 'checklist', 'VIII', NULL, 'How HNW bankers are paid', NULL, 'How would you mainly pay HNW bankers?', 'Tap one.', NULL, NULL, 'payModel', 'Tap one', TRUE);
